# Generated by Django 6.0.6 on 2026-10-26 (the schema operations), then the
# seed added by hand.
#
# Two new staff roles, BDE and Sales TL. Each gets a role group, linked to its
# role and carrying no permission: the catalogue has no entry either role may
# hold yet (accounts.permission_catalogue), so an account given one of them
# signs in to the Hub and reaches no data until permissions for their own
# modules are added -- in the catalogue and in a later migration.
#
# As in 0008, a group already carrying one of these names stops the migration
# rather than being adopted. No account row is touched.

from django.db import migrations, models

ROLE_GROUPS = (
    ('BDE', 'Role: BDE'),
    ('SALES_TL', 'Role: Sales TL'),
)


def seed_role_groups(apps, schema_editor):
    Group = apps.get_model('auth', 'Group')
    RoleGroup = apps.get_model('accounts', 'RoleGroup')
    db = schema_editor.connection.alias
    for role, name in ROLE_GROUPS:
        if RoleGroup.objects.using(db).filter(role=role).exists():
            continue
        if Group.objects.using(db).filter(name=name).exists():
            raise RuntimeError(
                f'A group named "{name}" already exists. Rename or remove it before migrating: '
                'the role groups are created here, never adopted.'
            )
        RoleGroup.objects.using(db).create(role=role, group=Group.objects.using(db).create(name=name))


def unseed_role_groups(apps, schema_editor):
    # Runs before the constraint goes back to Admin/Mentor/Tutor only.
    Group = apps.get_model('auth', 'Group')
    RoleGroup = apps.get_model('accounts', 'RoleGroup')
    db = schema_editor.connection.alias
    for link in RoleGroup.objects.using(db).filter(role__in=[role for role, _ in ROLE_GROUPS]):
        group_id = link.group_id
        link.delete()
        Group.objects.using(db).filter(pk=group_id).delete()


ROLE_CHOICES = [
    ('ADMIN', 'Admin'), ('MENTOR', 'Mentor'), ('TUTOR', 'Tutor'),
    ('BDE', 'BDE'), ('SALES_TL', 'Sales TL'), ('STUDENT', 'Student'),
]


class Migration(migrations.Migration):

    dependencies = [
        ('accounts', '0008_role_groups'),
        ('auth', '0012_alter_user_first_name_max_length'),
    ]

    operations = [
        migrations.RemoveConstraint(
            model_name='rolegroup',
            name='role_groups_staff_roles_only',
        ),
        migrations.AlterField(
            model_name='rolegroup',
            name='role',
            field=models.CharField(choices=ROLE_CHOICES, max_length=20, primary_key=True, serialize=False),
        ),
        migrations.AlterField(
            model_name='user',
            name='role',
            field=models.CharField(choices=ROLE_CHOICES, db_index=True, default='STUDENT', max_length=20),
        ),
        migrations.AddConstraint(
            model_name='rolegroup',
            constraint=models.CheckConstraint(
                condition=models.Q(('role__in', ['ADMIN', 'MENTOR', 'TUTOR', 'BDE', 'SALES_TL'])),
                name='role_groups_staff_roles_only',
            ),
        ),
        migrations.RunPython(seed_role_groups, unseed_role_groups),
    ]
